<script>
 let { data } = $props();
 let role = $state('Community representative');
 let name = $state(''); let email = $state(''); let message = $state(''); let prepared = $state(false);
 const pages = {
 'how-it-works':{tag:'THE GRIDUBUNTU MODEL',title:'Local sunshine.\nShared intelligently.',intro:'A connected approach to clean power, built around the way communities live and work.',items:[['01 / GENERATE','Start with the sun.','Solar generation supplies clean electricity to a connected community. The model brings local energy resources together rather than leaving each household to solve the challenge alone.'],['02 / STORE','Save sunshine for later.','Shared battery storage holds energy for use when solar generation falls. System design must account for local needs, storage capacity, and the loads people depend on.'],['03 / MANAGE','Make every unit count.','Our planned Energy Management System tracks energy contributions and consumption in real time, creating visibility into how energy moves through the shared system.'],['04 / BALANCE','Share with fairness in mind.','Automated load balancing is designed to match available supply to demand under agreed community rules. Forecasting draws on usage trends and weather data to help plan ahead.']]},
 'our-mission':{tag:'OUR PURPOSE',title:'Energy access is\nhuman possibility.',intro:'We are a Zimbabwean social enterprise working towards a future where clean, reliable power is within reach of underserved communities.',items:[['OUR BELIEF','Progress belongs to everyone.','Access to energy shapes the way people learn, earn, and connect. We believe the transition to renewable power should include households and small businesses whose needs are too often overlooked.'],['OUR APPROACH','Technology with a social purpose.','We are developing a shared solar storage model with intelligent energy management. Our aim is to use technology to support fair access, transparent participation, and a more resilient local energy supply.'],['OUR NAME','Ubuntu: I am because we are.','Our name reflects a simple conviction: communities are stronger when they build together. That spirit guides how we think about shared infrastructure, collective responsibility, and opportunity.'],['OUR COMMITMENT','Build with communities.','A useful energy solution starts with listening. Local priorities, practical operating rules, and a clear understanding of everyday energy needs should shape how the model develops.']]},
 'community':{tag:'POWER FOR EVERYDAY LIFE',title:'More than electricity.\nRoom to thrive.',intro:'The purpose of shared energy is what it makes possible for people. These are the everyday needs we are designing around.',items:[['FOR HOUSEHOLDS','Keep life moving after sunset.','Lighting for studying, charging for staying connected, and power for daily essentials. We want households to have a clearer path to reliable renewable energy.'],['FOR SMALL BUSINESSES','Give local enterprise room to grow.','From shops to workshops, dependable energy supports productive hours and everyday services. We are shaping our model around the practical needs of community businesses.'],['FOR COMMUNITY ORGANISERS','Shape a solution that fits.','Every community has its own priorities. Local representatives can help identify demand, understand participation, and develop fair rules for a shared energy system.'],['FOR A SHARED FUTURE','Make participation transparent.','Tracking contributions and consumption can make shared resources easier to understand. Clear information and agreed rules are central to the model we are building.']]}
 };
 let content = $derived(pages[data.slug]);
 function prepare(){prepared=true;}
 function download(){const blob=new Blob([`GridUbuntu enquiry\n\nName: ${name}\nEmail: ${email}\nInterest: ${role}\n\n${message}`],{type:'text/plain'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='gridubuntu-enquiry.txt';a.click();URL.revokeObjectURL(url);}
</script>
<svelte:head><title>{content ? content.title.replace('\n',' ') : 'Get involved'} — GridUbuntu</title><meta name="description" content={content?.intro || 'Explore ways to collaborate with GridUbuntu on accessible renewable energy for Zimbabwean communities.'}/></svelte:head>
{#if content}
<section class="page-hero"><div class="eyebrow">{content.tag}</div><h1 style="white-space:pre-line">{content.title}</h1><p>{content.intro}</p><span class="page-sun" aria-hidden="true">✳</span></section>
<section class="section story-list">{#each content.items as [tag,title,text]}<article><div class="eyebrow">{tag}</div><div><h2>{title}</h2><p>{text}</p></div></article>{/each}</section>
{#if data.slug==='how-it-works'}<section class="explainer section"><div><div class="eyebrow">INTELLIGENCE WITH PURPOSE</div><h2>A system that<br/>looks ahead.</h2><p>The EMS is being designed to combine live energy information with forecasts, helping the shared system respond to changing demand.</p><small>Conceptual model · not a live system dashboard</small></div><div class="flow"><div>Usage trends <span>↘</span></div><div>Weather data <span>→</span></div><strong>Energy Management System</strong><div>Forecast demand <span>↓</span></div><div>Balance available energy <span>⇄</span></div></div></section>{/if}
<section class="mission-band"><div class="eyebrow">BETTER, TOGETHER</div><h2>Help shape a brighter future.</h2><p>Bring your community perspective, expertise, or partnership idea to the conversation.</p><a class="button amber" href="/get-involved">Get involved ↗</a></section>
{:else}
<section class="page-hero"><div class="eyebrow">LET’S CONNECT</div><h1>A brighter future<br/>starts with us.</h1><p>We welcome community voices, technical collaborators, and partners who share our purpose.</p><span class="page-sun" aria-hidden="true">✳</span></section>
<section class="section contact-layout"><div><div class="eyebrow">FIND YOUR PLACE</div><h2>Bring your energy.</h2><p>Tell us what you’re interested in and how you would like to contribute.</p><div class="contact-note"><strong>A note on this website</strong><p>Our online enquiry service is not connected yet. You can prepare and download an enquiry below to share with your GridUbuntu contact. No information is submitted or stored by this site.</p></div><a class="text-link" href="/how-it-works">First, explore the model ↗</a></div><form onsubmit={(e)=>{e.preventDefault();prepare();}}><label for="name">Your name</label><input id="name" bind:value={name} required autocomplete="name" placeholder="Full name"/><label for="email">Email address</label><input id="email" type="email" bind:value={email} required autocomplete="email" placeholder="you@example.com"/><label for="role">I’m interested as a</label><select id="role" bind:value={role}><option>Community representative</option><option>Household or small business</option><option>Impact or development partner</option><option>Technology collaborator</option><option>Other</option></select><label for="message">What would you like to explore?</label><textarea id="message" bind:value={message} required rows="5" placeholder="Tell us about your community, organisation, or idea."></textarea><button class="button" type="submit">Prepare my enquiry ↗</button>{#if prepared}<div class="form-result" role="status"><strong>Your enquiry is ready to download.</strong><p>This has not been sent to GridUbuntu.</p><button type="button" class="text-link" onclick={download}>Download enquiry ↓</button></div>{/if}</form></section>
{/if}
